import pandas as pd
import re
file_path = '/data/mixed_units_register.xlsx'
df = pd.read_excel(file_path, sheet_name='Disbursement Register', header=5)
mask = df['Record ID'].astype(str).str.startswith('MU-')
df_valid = df[mask].copy()
def parse_amount(val):
    if pd.isna(val):
        return 0
    s = str(val).strip()
    if s in ('', '-', 'NA', 'Amount'):
        return 0
    # Remove rupee sign and commas
    s_clean = s.replace('₹','').replace(',','').strip()
    # Handle lakh, L, Cr, k
    # Patterns
    # e.g., 1.2 L, 2.5 lakh, 1 Cr, 45k, 340000
    # Use regex
    # Match number
    m = re.match(r'^([\d\.]+)\s*([a-zA-Z]+)?$', s_clean)
    if not m:
        # try numeric
        try:
            return float(s_clean)
        except:
            return 0
    num_str, unit = m.groups()
    try:
        num = float(num_str)
    except:
        num = 0
    unit = (unit or '').lower()
    if unit in ('l', 'lakh', 'lakhs'):
        return int(num * 100000)
    if unit == 'cr':
        return int(num * 10000000)
    if unit == 'k':
        return int(num * 1000)
    # No unit
    try:
        return int(float(s_clean))
    except:
        return 0
df_valid['Amount_INR'] = df_valid['Amount'].apply(parse_amount)
print(df_valid['Amount_INR'].head(20))
print(df_valid[['Record ID','Amount','Amount_INR']].head(30))
